  readonly cancelsTouchEnd?: boolean;
}

interface Guard {
  readonly unsubscribers: (() => void)[];
  timer: ReturnType<typeof setTimeout> | null;
}

/**
 * The click guard's state, registered, so a swizzled copy guards the same
 * clicks as the package.
