const guardState = realmValue(sharedKey('click-guard', 1), () => ({
  guards: new Map<Document, Guard>(),
  /** The click listeners that stay, by window: the menu press model's. */
  stayingClickListeners: new WeakMap<Window, () => void>(),
  unguardedDepth: 0,
}));
